import { useEffect, useRef } from "react";

/** 再試行/再読込ガード: 60秒窓で各1回のみ (無限ループ防止) */
const RESET_GUARD_KEY = "solopti.selfrecovery.error-reset-at";
const RELOAD_GUARD_KEY = "solopti.selfrecovery.error-reload-at";
const GUARD_WINDOW_MS = 60000;

/** 部品(chunk)読込失敗と判定するパターン (Next.js / Webpack / ES Modules 各系統) */
const CHUNK_ERROR_PATTERNS: RegExp[] = [
  /ChunkLoadError/i,
  /Loading chunk [^\s]+ failed/i,
  /Loading CSS chunk/i,
  /Failed to fetch dynamically imported module/i,
  /Importing a module script failed/i,
  /error loading dynamically imported module/i,
];

/** エラーオブジェクト/文字列から判定用テキストを安全に取り出す (画面には出さない) */
function textOf(input: unknown): string {
  if (!input) return "";
  if (typeof input === "string") return input;
  const obj = input as { name?: unknown; message?: unknown; digest?: unknown };
  const parts: string[] = [];
  if (typeof obj.name === "string") parts.push(obj.name);
  if (typeof obj.message === "string") parts.push(obj.message);
  if (typeof obj.digest === "string") parts.push(obj.digest);
  return parts.join(" ");
}

function withinGuard(key: string): boolean {
  try {
    const raw = window.sessionStorage.getItem(key);
    if (!raw) return false;
    const at = Number(raw);
    if (!Number.isFinite(at)) return false;
    return Date.now() - at < GUARD_WINDOW_MS;
  } catch (e) {
    // sessionStorage 不可 (プライベートモード等) はガード不能 = 安全側で「実施済み」とみなす
    return true;
  }
}

function markGuard(key: string): void {
  try {
    window.sessionStorage.setItem(key, String(Date.now()));
  } catch (e) {
    /* 記録できなくても処理は続ける */
  }
}

/**
 * 既存のエラー画面へ「自己回復のふるまい」だけを合流させるフック。
 * 画面表示は一切変更しない (このフックは何も描画しない)。
 *
 * 使い方: エラー画面コンポーネントの先頭で useSelfRecovery(error, reset) を呼ぶ。
 */
export function useSelfRecovery(error?: unknown, reset?: () => void): void {
  const done = useRef(false);
  useEffect(() => {
    if (done.current) return;
    done.current = true;
    if (typeof window === "undefined") return;

    const text = textOf(error);
    let isChunk = false;
    for (const pattern of CHUNK_ERROR_PATTERNS) {
      if (pattern.test(text)) {
        isChunk = true;
        break;
      }
    }

    // ① 部品読込失敗は再試行では直らない (古い chunk manifest を掴んだままのため)。
    //    60秒窓で1回だけ再読込する。
    if (isChunk) {
      if (withinGuard(RELOAD_GUARD_KEY)) return;
      markGuard(RELOAD_GUARD_KEY);
      const t = window.setTimeout(() => {
        try {
          window.location.reload();
        } catch (e) {
          /* 再読込できない環境では手動ボタンに委ねる */
        }
      }, 400);
      return () => window.clearTimeout(t);
    }

    // ② それ以外は Next.js の再試行を1回だけ自動で行う (お客様の操作を待たない)。
    if (typeof reset === "function") {
      if (withinGuard(RESET_GUARD_KEY)) return;
      markGuard(RESET_GUARD_KEY);
      const t = window.setTimeout(() => {
        try {
          reset();
        } catch (e) {
          /* 再試行できない場合は既存の手動ボタンに委ねる */
        }
      }, 400);
      return () => window.clearTimeout(t);
    }
    return;
  }, [error, reset]);
}

export default useSelfRecovery;
